<template>
  <section class="flex flex-col gap-4 md:gap-6">
    <PageTitle title="My Applications" show-doc>
      <NuxtLink :to="{ name: 'applications-upcoming' }">
        <Button>Upcoming Projects</Button>
      </NuxtLink>
    </PageTitle>
    <ApplicationsFilters :params="params" />
    <AppLoader v-if="isLoading" subject="applications" />
    <AppError v-else-if="error" :error="error" title="Failed to load applications" />
    <AppGuidedEmpty v-else-if="showGuided && guidedContent" v-bind="guidedContent" />
    <AppEmpty v-else-if="isEmpty" subject="applications" />
    <section v-else class="flex flex-col gap-4">
      <ApplicationsItem v-for="item in applications" :key="item.id" :item="item" />
      <AppPagination :page="params.page" :size="params.size" :total="total" label="applications" />
    </section>
  </section>
</template>

<script setup lang="ts">
import { myApplicationsGuidedEmpty } from '~/constants/guidedEmpty/applications';
import {
  getAppliedProjectsForCanvasser,
  type ProjectSortBy,
  type ProjectApplicationStatus,
  type SortType,
  type GetAppliedProjectsForCanvasserData,
} from '~/client';

useHead({
  title: 'My Applications',
});

definePageMeta({
  roles: ['canvasser'],
  backLabel: 'applications',
});

const route = useRoute();

const params = computed<GetAppliedProjectsForCanvasserData['query']>(() => {
  const urlParams = {
    page: Number(route.query.page) || 1,
    size: Number(route.query.size) || 10,
    sort_by: (route.query.sort_by as ProjectSortBy) || 'start_date',
    sort_type: isSortType(route.query.sort_type as string) ? (route.query.sort_type as SortType) : 'desc',
    from_date: isDate((route.query.from_date as string) || '') ? (route.query.from_date as string) : undefined,
    name: (route.query.name as string) || undefined,
    application_statuses: processArrayQueryParameterFromUrl<ProjectApplicationStatus>(route.query.application_statuses),
    type: (route.query.type as string) || undefined,
  };

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as unknown as GetAppliedProjectsForCanvasserData['query'];
});

const {
  data: applicationsData,
  error,
  isLoading,
} = useQuery({
  key: () => ['applications.mylist', params.value || ''],
  query: () => {
    return getAppliedProjectsForCanvasser({
      composable: '$fetch',
      query: ref(params.value || {}),
    });
  },
  staleTime: 0,
});

const applications = computed(() => applicationsData.value?.items ?? []);
const total = computed(() => applicationsData.value?.total_count ?? 0);

const isEmpty = computed(() => !applications.value || applications.value.length === 0);

const { guidedContent, showGuided } = useGuidedEmpty(myApplicationsGuidedEmpty, isEmpty);
</script>

<style scoped lang="scss"></style>
